import { stdout } from std.io;
contract Speak { speak(): String; }
trait Describable {
    type_name(): String;
    describe(): String { return "value of " + this.type_name(); }
}
class Dog implements Speak, Describable {
    construct() { }
    speak(): String { return "woof"; }
    type_name(): String { return "Dog"; }
}
class Cat implements Speak, Describable {
    construct() { }
    speak(): String { return "meow"; }
    type_name(): String { return "Cat"; }
    #override describe(): String { return "a cat"; }
}
fn talk(s: Speak): Void { stdout.println(s.speak()); }
fn main(): Void {
    talk(Dog());
    talk(Cat());
    inmut d = Dog();
    inmut c = Cat();
    stdout.println(d.describe());
    stdout.println(c.describe());
}
